submissions.repair-original-reconcile-early-transfer:
def solve(data):
    cutoff = data['cutoff']
    received = {}
    for row in data['receipts']:
        if row['state'] == 'accepted' and row['at'] <= cutoff:
            transfer = row['transfer']
            received[transfer] = received.get(transfer, 0) + row['units']
    result = []
    for post in data['postings']:
        if post['state'] == 'posted' and post['at'] <= cutoff:
            transfer = post['transfer']
            remaining = post['units'] - received.get(transfer, 0)
            result.append({'transfer': transfer, 'remaining': remaining})
    return sorted(result, key=lambda row: row['transfer'])

submissions.repair-original-retain-interpolation-bou:
def solve(data):
    start = data['start']
    readings = {}
    for row in data['samples']:
        minute = row['minute']
        if row['state'] == 'verified' and minute <= data['end']:
            readings[minute] = row['temp_c']
    if start in readings:
        return {'opening_c': readings[start]}
    left = max((m for m in readings if m < start), default=None)
    right = min((m for m in readings if m > start), default=None)
    if left is None or right is None:
        return {'opening_c': None}
    numerator = readings[left] * (right - start) + readings[right] * (start - left)
    return {'opening_c': numerator / (right - left)}

submissions.repair-original-round-fiscal-week:
def solve(data):
    week = data['week']
    checkpoints = list(range(1, 50, 4)) + [data['weeks']]
    return min(checkpoints, key=lambda point: (abs(point - week), -point))

submissions.repair-original-schedule-marker-covering:
def solve(data):
    cues = sorted((cue for cue in data['cues'] if cue['state'] == 'cleared'), key=lambda cue: cue['start'])
    marker = data['marker']
    best = None
    for mask in range(1, 1 << len(cues)):
        chosen = [cue for i, cue in enumerate(cues) if mask & (1 << i)]
        if any(a['end'] > b['start'] for a, b in zip(chosen, chosen[1:])):
            continue
        if not any(cue['start'] <= marker < cue['end'] for cue in chosen):
            continue
        ids = [cue['id'] for cue in chosen]
        rank = (-sum(cue['score'] for cue in chosen), len(ids), ids)
        if best is None or rank < best:
            best = rank
    return [] if best is None else best[2]
